delete from public.pruef_einheiten where thema_id = 14;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6983, 14, 'Zentrales Portal oder App mit digitaler Identität für alle Verwaltungsleistungen', 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'gemischt', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'bund', null, true, null),
  (6984, 14, 'Once-Only: Register vernetzen, Daten nur einmal angeben', 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'belegt', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'bund', null, true, null),
  (6985, 14, 'Zuständigkeit für Verwaltungsdigitalisierung in einem Digitalministerium bündeln', 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'offen', null, 'bund', null, true, null),
  (6986, 14, 'Automatisierung, KI und antragslose Verfahren in der Verwaltung', 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'gemischt', null, 'bund', null, true, null),
  (6987, 14, 'Öffentlichen Dienst als Arbeitgeber attraktiver machen', 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'gemischt', null, 'bund', null, true, null),
  (6988, 14, 'Mehr Ermessen für Behörden, Regeln auf den Regelfall ausrichten', 'Kann Entscheidungen beschleunigen und Einzelfallprüfungen vermeiden; wie stark Vorschriften dadurch tatsächlich schlanker werden, ist offen.', 'offen', null, 'bund', null, true, null),
  (7125, 14, 'Verwaltungsleistungen im Land durchgängig digital, zentrales Portal oder App (Landesprogramm)', 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'gemischt', null, 'land', null, true, null),
  (7126, 14, 'Verwaltungsmodernisierung zentral im Land bündeln (Landesprogramm)', 'Klare Zuständigkeit kann Digitalisierungsprojekte beschleunigen; für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich einfacher werden.', 'offen', null, 'land', null, true, null),
  (7127, 14, 'KI und Automatisierung zur Entlastung der Verwaltung (Landesprogramm)', 'Kann Personalmangel abfedern und Bearbeitungszeiten senken; Voraussetzung sind digitale Akten und Daten, die vielerorts fehlen.', 'gemischt', null, 'land', null, true, null),
  (7128, 14, 'Öffentlichen Dienst im Land attraktiver machen: Ausbildung, Bezahlung, Arbeitsbedingungen (Landesprogramm)', 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'gemischt', null, 'land', null, true, null),
  (7129, 14, 'Terminvergabe in Bürgerämtern verbessern (Landesprogramm)', 'Verteilt vorhandene Termine besser und verkürzt Wartezeiten etwas; mehr Kapazität entsteht dadurch nicht.', 'offen', null, 'land', null, true, null)
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

