  (6989, 14, 11, null, 'Sichere digitale Identität mit eigenem Postfach für Behördengänge (DeutschlandID)', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=29', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (6990, 14, 11, null, 'Bundesdigitalministerium einrichten', '{1401}', 6985, 1, 3, null, 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=30', null, 'offen', '2026-09-30', false, true, null),
  (6991, 14, 11, null, 'Once-Only-Prinzip konsequent umsetzen', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=79', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (6992, 14, 11, null, 'Digitalen Vollzug zum Standard machen', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=79', null, 'gemischt', '2026-09-30', false, true, null),
  (6993, 14, 11, null, 'Gesetze auf den Regelfall ausrichten, mehr Ermessen, Experimentierklausel', '{1404}', 6988, 1, 3, null, 'Kann Entscheidungen beschleunigen und Einzelfallprüfungen vermeiden; wie stark Vorschriften dadurch tatsächlich schlanker werden, ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=79', null, 'offen', '2026-09-30', false, true, null),
  (6994, 14, 12, null, 'Alle Zuständigkeiten der Verwaltungsdigitalisierung in einem Ministerium bündeln', '{1401}', 6985, 1, 3, null, 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'offen', '2026-09-30', false, true, null),
  (6995, 14, 12, null, 'System der einmaligen Datenübermittlung, Staatsvertrag mit den Ländern, Registermodernisierung', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (6996, 14, 12, null, 'DeutschlandID für zentralen Zugang zu Verwaltungsdiensten', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
