  (6998, 14, 12, null, 'Staat als Arbeitgeber attraktiver machen: Homeoffice, Job-Sharing, weniger Befristungen', '{1402}', 6987, 2, 1, null, 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'gemischt', '2026-09-30', false, true, null),
  (6999, 14, 13, null, 'Deutschland-App für alle Verwaltungsleistungen, gemeinsam mit Ländern und Kommunen', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (7000, 14, 13, null, 'Automatisierung, KI und antragslose Verfahren', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (7001, 14, 13, null, 'Ermessensspielräume der Entscheider erhöhen', '{1404}', 6988, 1, 3, null, 'Kann Entscheidungen beschleunigen und Einzelfallprüfungen vermeiden; wie stark Vorschriften dadurch tatsächlich schlanker werden, ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', null, 'offen', '2026-09-30', false, true, null),
  (7002, 14, 13, null, 'Registermodernisierung und -vernetzung, Daten nur einmal einpflegen', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (7003, 14, 14, null, 'Once-only-Garantie, alle relevanten Register digitalisieren und vernetzen', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=38', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (7004, 14, 14, null, 'Bundesministerium für Digitalisierung mit Befugnissen für die Verwaltungsdigitalisierung', '{1401}', 6985, 1, 3, null, 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=38', null, 'offen', '2026-09-30', false, true, null),
  (7005, 14, 14, null, 'Government as a Platform mit allen digitalen Verwaltungsanwendungen, digitale Wallet', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=39', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (7006, 14, 14, null, 'Weniger Ministerien und Behörden, klarere Zuständigkeiten', '{1404}', null, 1, 3, null, 'Klarere Zuständigkeiten können Abstimmungen verkürzen; die Bundesministerien haben aber wenig direkten Kontakt mit Bürgerinnen und Bürgern, und an der Menge der Vorschriften ändert das wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=37', null, 'offen', '2026-09-30', false, true, null),
  (7007, 14, 15, null, 'Digitalisierung der Verwaltung vorantreiben', '{1401}', null, 1, 3, null, 'Nennt das Ziel, aber keinen Weg.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'offen', '2026-09-30', false, true, null),
  (7008, 14, 16, null, 'Geräte und fachkundiges Personal vor Ort, um beim Ausfüllen von Onlineanträgen zu helfen', '{1401}', null, 1, 1, null, 'Hilft Menschen, die mit Onlineanträgen nicht zurechtkommen; an der Bearbeitung ändert es nichts und braucht zusätzliches Personal in Kommunen, auf die der Bund kaum Zugriff hat.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'offen', '2026-09-30', false, true, null),
