  (7139, 14, 11, 'MV', 'Alle Behördengänge bis 2030 digital über das MV-Serviceportal (One-Stop-Government)', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=101', null, 'gemischt', '2026-09-30', false, true, null),
