  (7141, 14, 13, 'MV', 'Familienfreundliche Arbeitsmodelle im öffentlichen Dienst', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://gruene-mv.de/?wpdmdl=33772#page=84', null, 'gemischt', '2026-09-30', false, true, null),
  (7142, 14, 14, 'MV', 'MV-Serviceportal zum One-Stop-Shop mit Ende-zu-Ende-Verfahren und Fristen, Anlaufstellen vor Ort', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=57', null, 'gemischt', '2026-09-30', false, true, null),
  (7143, 14, 15, 'MV', 'Digitalisierung und Prozessoptimierung im öffentlichen Dienst, um Kapazitäten freizusetzen', '{1401,1402}', 7127, 2, 2, null, 'Kann Personalmangel abfedern und Bearbeitungszeiten senken; Voraussetzung sind digitale Akten und Daten, die vielerorts fehlen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=15', null, 'gemischt', '2026-09-30', false, true, null),
  (7144, 14, 16, 'MV', 'Familienfreundliche Arbeitsmodelle im öffentlichen Dienst ausbauen', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', null, 'gemischt', '2026-09-30', false, true, null),
  (7145, 14, 17, 'MV', 'Medienbruchfreie Verfahren, verbindliche Standards, erst vereinfachen, dann digitalisieren', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=91', null, 'gemischt', '2026-09-30', false, true, null),
  (7146, 14, 17, 'MV', 'Gute Arbeitsbedingungen und Qualifizierung für Verwaltungsbeschäftigte', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', null, 'gemischt', '2026-09-30', false, true, null),
  (7147, 14, 11, 'BE', 'Verwaltungsinterne Abläufe konsequent digital abbilden', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=89', null, 'gemischt', '2026-09-30', false, true, null),
  (7148, 14, 11, 'BE', 'Entlastung durch KI bei standardisierten Aufgaben in Bezirken und nachgeordneten Bereichen', '{1401,1402}', 7127, 2, 2, null, 'Kann Personalmangel abfedern und Bearbeitungszeiten senken; Voraussetzung sind digitale Akten und Daten, die vielerorts fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=90', null, 'gemischt', '2026-09-30', false, true, null),
  (7149, 14, 12, 'BE', 'Berlin-App nach Wiener Vorbild, Digitallotsen, mobile Angebote in den Kiezen', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=61', null, 'gemischt', '2026-09-30', false, true, null),
  (7150, 14, 12, 'BE', 'Beschäftigtenwohnungen für die Personalgewinnung, Personalaufgaben bündeln', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=61', null, 'gemischt', '2026-09-30', false, true, null),
  (7151, 14, 13, 'BE', 'Ausbildungsoffensive für den öffentlichen Dienst, Beschäftigtenwohnen', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=247', null, 'gemischt', '2026-09-30', false, true, null),
  (7152, 14, 13, 'BE', 'Digitalgesetz für Berlin vollenden, Verwaltungsdigitalisierung umsetzen', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=249', null, 'gemischt', '2026-09-30', false, true, null),
  (7153, 14, 14, 'BE', 'Alle Behördengänge rund um die Uhr über ein digitales Rathaus', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (7154, 14, 14, 'BE', 'KI-System für Bürgeramtstermine, digitale Warteliste für stornierte Termine', '{1401,1402}', 7129, 1, 3, null, 'Verteilt vorhandene Termine besser und verkürzt Wartezeiten etwas; mehr Kapazität entsteht dadurch nicht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=91', null, 'offen', '2026-09-30', false, true, null),
  (7155, 14, 15, 'BE', 'Strategische Digitalisierung der Verwaltung', '{1401}', null, 1, 3, null, 'Nennt das Ziel einer effizienten, digitalen Verwaltung, aber keinen konkreten Weg für Bürgerinnen und Bürger.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=18', null, 'offen', '2026-09-30', false, true, null),
  (7156, 14, 16, 'BE', 'Verwaltung digitaler und effizienter machen, Verwaltungsreform umsetzen', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=11', null, 'gemischt', '2026-09-30', false, true, null),
  (7157, 14, 17, 'BE', 'Konkurrenzfähige Gehälter für IT-Fachkräfte im öffentlichen Dienst', '{1401,1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=66', null, 'gemischt', '2026-09-30', false, true, null),
  (7225, 14, 14, null, 'Vorausgefüllte Steuererklärung bis zur vollautomatisierten Einkommensteuerveranlagung („Easy Tax“)', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'gemischt', '2026-09-30', false, true, null),
  (7226, 14, 14, null, 'Elterngeld und Familienleistungen digitalisieren und automatisieren, KI-basierte Beantragung', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (8548, 14, 18, null, 'Zentrales Digitalministerium mit Richtlinienkompetenz für alle Verwaltungsebenen und bundeseinheitlichen Standards für durchgängige Digitalisierung der Verwaltung.', '{1401}', null, 2, 1, null, 'Verbindliche einheitliche Standards setzen an der Zersplitterung der IT von Bund und Ländern an, die Fachleute als Hauptbremse nennen. Eine Richtlinienkompetenz für alle Ebenen braucht aber eine Grundgesetzänderung (Art. 91c), Erfahrungen damit fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=28', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8549, 14, 18, null, 'Verwaltungsleistungen proaktiv, automatisiert, mobil und mit E-Identifikation und E-Payment bereitstellen.', '{1401}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=29', null, 'gemischt', '2026-10-07', false, true, null),
  (8550, 14, 18, null, 'Once-Only-Prinzip konsequent umsetzen: Daten werden nur einmal übermittelt und von Behörden gemeinsam genutzt, bei gewährleistetem Datenschutz.', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=29', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-10-07', false, true, null),
  (8551, 14, 18, null, 'Zentrale Anlaufstellen, automatische Genehmigung bei verspäteter Bearbeitung und regelmäßige Überprüfung von Vorschriften.', '{1404}', null, 2, 2, null, 'Regelmäßige Überprüfung von Vorschriften und Genehmigungsfiktion können Verfahren straffen; Behörden könnten aber vorsorglich ablehnen, die Fiktion ersetzt keine Prüfung, und ihre Wirkung ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=17', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8552, 14, 18, null, 'Zuständigkeiten zwischen Bund, Ländern und Kommunen neu ordnen.', '{1404}', null, 1, 1, null, 'Klarere Zuständigkeiten könnten Doppelarbeit und Aufgabenlast verringern; die Zusage bleibt unbestimmt, braucht Grundgesetzänderungen mit Zustimmung der Länder, und die Bilanz früherer Föderalismusreformen ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=15', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8553, 14, 18, null, 'Angepasste Gehaltsstrukturen, Beamtentum auf Zeit und Personalrotation für die Verwaltung.', '{1402}', 6987, 2, 1, null, 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=17', null, 'gemischt', '2026-10-07', false, true, null),
  (8712, 14, 18, 'BE', 'Einheitliches, mehrsprachiges Serviceportal für zentrale Verwaltungsleistungen, Anträge vollständig online, mit Statusanzeige.', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=15', null, 'gemischt', '2026-10-08', false, true, null),
  (8713, 14, 18, 'BE', 'E-Akte flächendeckend und verbindlich ausbauen, damit digitale Vorgänge nicht ausgedruckt und neu erfasst werden.', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=14', null, 'gemischt', '2026-10-08', false, true, null),
  (8714, 14, 18, 'BE', 'KI in der Verwaltung zur Vorprüfung von Anträgen, Vollständigkeitsprüfung, Priorisierung und Bescheidentwürfen einsetzen.', '{1402}', 7127, 2, 2, null, 'Kann Personalmangel abfedern und Bearbeitungszeiten senken; Voraussetzung sind digitale Akten und Daten, die vielerorts fehlen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=15', null, 'gemischt', '2026-10-08', false, true, null),
  (8715, 14, 18, 'BE', 'Besoldung der Berliner Verwaltung an Bundesniveau angleichen, Zulagen für gefragte Berufsgruppen.', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=17', null, 'gemischt', '2026-10-08', false, true, null),
  (8716, 14, 18, 'MV', 'Einheitliche digitale Bürgerplattform für alle Verwaltungsleistungen im Land, bis 2030', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=43', null, 'gemischt', '2026-10-08', false, true, null),
  (8717, 14, 18, 'MV', 'Durchgängig digitale Akten, transparente Bearbeitungsstände und einmalige Datenangabe (Once-Only)', '{1401}', null, 2, 2, null, 'Digitale Akten und Once-Only setzen an Medienbrüchen und doppelten Nachweisen an, die Nutzer als größte Ärgernisse nennen. Das Land kann eigene Register vernetzen, volle Wirkung braucht aber die mehrjährige Registermodernisierung mit Bund und Kommunen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=43', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8718, 14, 18, 'MV', 'KI-gestützte Automatisierung und Standardisierung in der Ministerialverwaltung, Stellenabbau über Neubesetzungssperren', '{1402}', null, 1, 2, null, 'Automatisierung kann Routinearbeit abnehmen; Modellrechnungen sehen Potenzial, aber kein Allheilmittel. Die Einsparung betrifft die Ministerialverwaltung ohne Bürgerkontakt, und eine feste Stellenkürzung verbraucht den Gewinn, statt Engpässe zu lindern.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=23', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8719, 14, 18, 'ST', 'Einheitliche digitale Landesplattform für alle Verwaltungsleistungen bis 2030, OZG konsequent umsetzen', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=106', null, 'gemischt', '2026-10-08', false, true, null),
  (8720, 14, 18, 'ST', 'Vollständig digitale, medienbruchfreie Verfahren von der Antragstellung bis zum Bescheid', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=106', null, 'gemischt', '2026-10-08', false, true, null),
  (8721, 14, 18, 'ST', 'Tools, die Formulare mit wenigen Klicks automatisiert ausfüllen', '{1401}', null, 1, 3, null, 'Einfacheres Ausfüllen senkt eine Hürde, die Nutzer bei komplizierten Anträgen nennen; ob Anträge dadurch schneller bearbeitet werden, hängt von der digitalen Bearbeitung dahinter ab und ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=117', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'offen', '2026-10-08', false, true, 'blind');

